"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyFlowchart from "../beautiful-ui/primitives/Flowchart";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type FlowchartProps = NonNullable<ComponentProps<typeof LegacyFlowchart>>;

export const Flowchart = forwardRef<HTMLDivElement, FlowchartProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyFlowchart {...props} />
  </BeautifulUIRoot>
));

Flowchart.displayName = "Flowchart";

export default Flowchart;

"use client";

import { useEffect, useRef, useState } from "react";
import { useLayoutEffect } from "react";
import { nestedRadius, useShape } from "@/lib/shape-context";
import { useSurface } from "@/lib/surface-context";
import { surfaceClasses } from "@/lib/surface-classes";
import { Elevated } from "@/lib/elevated";
import "../beautiful-ui.css";

/* ─────────────────────────────────────────────────────────
 * FLOWCHART — an agent workflow on a dotted editor canvas.
 * Two steps: a Trigger card and an If/Else condition card,
 * joined by a measured connector. Cards drag anywhere on
 * the canvas; the connector follows. Condition chips open
 * real dropdowns (same menu as the PromptBar model picker).
 * ───────────────────────────────────────────────────────── */

const PURPLE = "var(--purple)";
const AMBER = "var(--amber)";

const mix = (hue: string, pct: number, base = "var(--surface)") =>
  `color-mix(in srgb, ${hue} ${pct}%, ${base})`;

/* ── layout constants ── */
const PAD_Y = 24;
const ROW_GAP = 64;
const PILL_OFFSET = 30; // kind pill + gap above a card

type StepNode = {
  id: string;
  row: number;
  x: number; // 0–1 center of the node
  w: number;
  kind?: { label: string; hue: string };
  hue?: string;
  title?: string;
  caption?: string;
  condition?: boolean; // renders the if/else chip rows instead
};

const NODES: StepNode[] = [
  {
    id: "trigger",
    row: 0,
    x: 0.5,
    w: 300,
    kind: { label: "Trigger", hue: PURPLE },
    hue: PURPLE,
    title: "New order created",
    caption: "Trigger when a new order is created",
  },
  {
    id: "cond",
    row: 1,
    x: 0.5,
    w: 356,
    kind: { label: "If / Else", hue: AMBER },
    condition: true,
  },
];

const EDGES = [{ from: "trigger", to: "cond" }];

/* estimated heights for the first paint; measured immediately after */
const EST_H: Record<string, number> = { trigger: 92, cond: 134 };

const PROPERTIES = ["flavor", "topping", "size", "scoops"];
const FLAVORS = [
  { name: "Rocky Road", tag: "Classic" },
  { name: "Mint Chip", tag: "Classic" },
  { name: "Pistachio", tag: "Seasonal" },
  { name: "Bubblegum", tag: "Retro" },
];
const TOPPINGS = [
  { name: "Brown butter bourbon brittle crunch" },
  { name: "Rainbow sprinkles" },
  { name: "Hot fudge" },
  { name: "Candied pecans" },
];

/* ── icons ── */
function ConeIcon({ size = 16 }: { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="m7 11 4.08 10.35a1 1 0 0 0 1.84 0L17 11" />
      <path d="M17 7A5 5 0 0 0 7 7" />
      <path d="M17 7a2 2 0 0 1 0 4H7a2 2 0 0 1 0-4" />
    </svg>
  );
}

function Chevron() {
  return (
    <svg
      width="11"
      height="11"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="shrink-0 text-[var(--ink-3)]"
    >
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

function Handle() {
  return (
    <svg
      width="10"
      height="16"
      viewBox="0 0 10 16"
      className="shrink-0 cursor-grab text-[var(--ink-3)]/70"
    >
      {[3, 8, 13].flatMap((y) => [
        <circle key={`l${y}`} cx="3" cy={y} r="1.1" fill="currentColor" />,
        <circle key={`r${y}`} cx="7.5" cy={y} r="1.1" fill="currentColor" />,
      ])}
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg
      width="13"
      height="13"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M20 6L9 17l-5-5" />
    </svg>
  );
}

/* ── dropdown menu — same pattern as the PromptBar model picker ── */
function Menu({
  id,
  items,
  value,
  width,
  align,
  onPick,
  onClose,
}: {
  id: string;
  items: { name: string; tag?: string }[];
  value: string;
  width: string;
  align: "left" | "right";
  onPick: (name: string) => void;
  onClose: () => void;
}) {
  const shape = useShape();
  const [hovered, setHovered] = useState<number | null>(null);
  const rowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);

  const valueIndex = items.findIndex((item) => item.name === value);
  useLayoutEffect(() => {
    const row = rowRefs.current[hovered ?? valueIndex];
    if (row) setBox({ top: row.offsetTop, height: row.offsetHeight });
  }, [hovered, valueIndex]);

  useEffect(() => {
    rowRefs.current[Math.max(0, valueIndex)]?.focus();
  }, [valueIndex]);

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      onClose();
      return;
    }
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const items = rowRefs.current.filter((item): item is HTMLButtonElement => Boolean(item));
    if (!items.length) return;
    event.preventDefault();
    const current = Math.max(0, items.indexOf(document.activeElement as HTMLButtonElement));
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? items.length - 1
          : event.key === "ArrowDown"
            ? (current + 1) % items.length
            : (current - 1 + items.length) % items.length;
    items[next]?.focus();
  };

  return (
    <Elevated
      offset={2}
      shadowLevel={3}
      id={id}
      role="listbox"
      aria-label="Choose a condition value"
      onKeyDown={onKeyDown}
      onMouseLeave={() => setHovered(null)}
      className={`absolute bottom-full z-20 mb-1.5 max-w-[calc(100vw-48px)] ${shape.container} p-1 ${width}
        ${align === "right" ? "right-0" : "left-0"}`}
      style={{
        animation: "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
        transformOrigin: align === "right" ? "bottom right" : "bottom left",
      }}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute inset-x-1 ${shape.item} bg-[var(--hover)]`}
        style={{
          top: box?.top ?? 0,
          height: box?.height ?? 0,
          opacity: box && hovered !== null ? 1 : 0,
          transition:
            "top 240ms cubic-bezier(0.23,1,0.32,1), height 240ms cubic-bezier(0.23,1,0.32,1), opacity 160ms ease",
        }}
      />
      {items.map((item, i) => (
        <button
          key={item.name}
          type="button"
          role="option"
          aria-selected={item.name === value}
          ref={(el) => {
            rowRefs.current[i] = el;
          }}
          onMouseEnter={() => setHovered(i)}
          onClick={() => onPick(item.name)}
          className={`relative z-10 flex h-8 w-full cursor-pointer items-center gap-2 ${shape.item} px-2 text-left`}
        >
          <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-[var(--ink)]">
            {item.name}
          </span>
          {item.tag && <span className="shrink-0 text-[11px] text-[var(--ink-3)]">{item.tag}</span>}
          <span className={`shrink-0 text-[var(--ink)] ${item.name === value ? "" : "invisible"}`}>
            <CheckIcon />
          </span>
        </button>
      ))}
    </Elevated>
  );
}

/* ── chips used inside the condition card ── */
function SourceChip() {
  const shape = useShape();
  return (
    <span
      data-ui
      className={`inline-flex h-6 shrink-0 items-center gap-1 ${shape.item} bg-[var(--surface)] px-1.5 text-[12px] font-medium text-[var(--ink)] shadow-[var(--shadow-btn)]`}
    >
      <span className="text-[var(--ink-2)]">
        <ConeIcon size={12} />
      </span>
      order
    </span>
  );
}

function SelectChip({
  id,
  value,
  dot,
  items,
  width,
  align = "left",
  open,
  onToggle,
  onPick,
}: {
  id: string;
  value: string;
  dot?: boolean;
  items: { name: string; tag?: string }[];
  width: string;
  align?: "left" | "right";
  open: boolean;
  onToggle: (id: string) => void;
  onPick: (id: string, name: string) => void;
}) {
  const shape = useShape();
  const substrate = useSurface();
  const controlLevel = Math.min(substrate + 1, 8);
  const triggerRef = useRef<HTMLButtonElement>(null);

  return (
    <span data-ui className="relative inline-flex min-w-0 max-w-full">
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`flow-menu-${id}`}
        onClick={() => onToggle(id)}
        className={`group/flow-chip relative isolate inline-flex h-7 min-w-0 max-w-full cursor-pointer appearance-none items-center gap-1 border-0 ${shape.button} ${surfaceClasses(controlLevel, 1)} px-2
          text-[12px] font-medium text-[var(--ink)] active:scale-[0.98]`}
      >
        <span
          aria-hidden
          className={`pointer-events-none absolute inset-0 -z-10 rounded-[inherit] transition-colors duration-80 ${
            open ? "bg-active" : "bg-transparent group-hover/flow-chip:bg-hover"
          }`}
        />
        {dot && <span className="size-1.5 shrink-0 rounded-full" style={{ background: AMBER }} />}
        <span className="min-w-0 truncate">{value}</span>
        <Chevron />
      </button>
      {open && (
        <Menu
          id={`flow-menu-${id}`}
          items={items}
          value={value}
          width={width}
          align={align}
          onPick={(name) => onPick(id, name)}
          onClose={() => {
            onToggle(id);
            requestAnimationFrame(() => triggerRef.current?.focus());
          }}
        />
      )}
    </span>
  );
}

function ConditionBody({ onChange }: { onChange?: (values: Record<string, string>) => void }) {
  const [values, setValues] = useState<Record<string, string>>({
    prop1: "flavor",
    val1: "Rocky Road",
    prop2: "topping",
    val2: "Brown butter bourbon brittle crunch",
  });
  const [open, setOpen] = useState<string | null>(null);

  /* click anywhere else closes the menu */
  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-ui]")) setOpen(null);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [open]);

  const toggle = (id: string) => setOpen((current) => (current === id ? null : id));
  const pick = (id: string, name: string) => {
    setValues((current) => {
      const next = { ...current, [id]: name };
      onChange?.(next);
      return next;
    });
    setOpen(null);
  };

  const chip = (
    id: string,
    items: { name: string; tag?: string }[],
    width: string,
    extra?: object,
  ) => (
    <SelectChip
      id={id}
      value={values[id]}
      items={items}
      width={width}
      open={open === id}
      onToggle={toggle}
      onPick={pick}
      {...extra}
    />
  );

  return (
    <div className="flex flex-col gap-1.5 px-3 py-2.5">
      <div className="flex min-w-0 flex-wrap items-center gap-1.5">
        <Handle />
        <span className="w-7 text-[13px] text-[var(--ink-2)]">If</span>
        <SourceChip />
        {chip(
          "prop1",
          PROPERTIES.map((name) => ({ name })),
          "w-36",
        )}
        <span className="text-[13px] text-[var(--ink-2)]">is</span>
        {chip("val1", FLAVORS, "w-44", { dot: true, align: "right" })}
      </div>
      <div className="flex min-w-0 flex-wrap items-center gap-x-1.5 gap-y-1.5">
        <Handle />
        <span className="w-7 text-[13px] text-[var(--ink-2)]">and</span>
        <SourceChip />
        {chip(
          "prop2",
          PROPERTIES.map((name) => ({ name })),
          "w-36",
        )}
        <span className="text-[13px] text-[var(--ink-2)]">is</span>
        <span className="max-w-full">{chip("val2", TOPPINGS, "w-64", { dot: true })}</span>
      </div>
    </div>
  );
}

function StepBody({ node }: { node: StepNode }) {
  const shape = useShape();
  return (
    <div className="flex items-center gap-2.5 px-3 py-2.5">
      <span
        className="flex size-9 shrink-0 items-center justify-center"
        style={{
          // Node content is inset 10px vertically and 12px horizontally.
          borderRadius: nestedRadius(shape.containerRadius, 10),
          background: mix(node.hue!, 12),
          color: node.hue,
          boxShadow: `0 0 0 1px ${mix(node.hue!, 20)}`,
        }}
      >
        <ConeIcon />
      </span>
      <span className="min-w-0 text-left">
        <span className="block truncate text-[13px] font-semibold text-[var(--ink)]">
          {node.title}
        </span>
        <span className="mt-0.5 block text-[12px] leading-snug text-[var(--ink-2)]">
          {node.caption}
        </span>
      </span>
    </div>
  );
}

/* ── the canvas ── */
export interface FlowchartProps {
  onNodeMove?: (nodeId: string, offset: { dx: number; dy: number }) => void;
  onConditionChange?: (values: Record<string, string>) => void;
}

export default function Flowchart({ onNodeMove, onConditionChange }: FlowchartProps = {}) {
  const shape = useShape();
  const canvasRef = useRef<HTMLDivElement>(null);
  const nodeRefs = useRef(new Map<string, HTMLElement>());
  const [width, setWidth] = useState(0);
  const [heights, setHeights] = useState<Record<string, number>>(EST_H);
  const [selected, setSelected] = useState<string | null>(null);
  const [offsets, setOffsets] = useState<Record<string, { dx: number; dy: number }>>({});
  const drag = useRef<{
    id: string;
    startX: number;
    startY: number;
    baseDx: number;
    baseDy: number;
    moved: boolean;
  } | null>(null);

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const measure = () => {
      setWidth(canvas.clientWidth);
      setHeights((prev) => {
        const next = { ...prev };
        let changed = false;
        nodeRefs.current.forEach((el, id) => {
          const h = el.offsetHeight;
          if (h && Math.abs(h - (next[id] ?? 0)) > 0.5) {
            next[id] = h;
            changed = true;
          }
        });
        return changed ? next : prev;
      });
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(canvas);
    nodeRefs.current.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  /* rows → y offsets from measured node heights */
  const rows = [...new Set(NODES.map((n) => n.row))].sort((a, b) => a - b);
  const rowH = rows.map((r) =>
    Math.max(...NODES.filter((n) => n.row === r).map((n) => heights[n.id] ?? 90)),
  );
  const rowY: number[] = [];
  rows.forEach((_, i) => {
    rowY[i] = i === 0 ? PAD_Y : rowY[i - 1] + rowH[i - 1] + ROW_GAP;
  });
  const canvasH = rowY[rows.length - 1] + rowH[rows.length - 1] + PAD_Y;

  const cw = width || 480;
  const place = (n: StepNode) => {
    const w = Math.min(n.w, cw * 0.92);
    const off = offsets[n.id];
    return {
      w,
      cx: n.x * cw + (off?.dx ?? 0),
      top: rowY[rows.indexOf(n.row)] + (off?.dy ?? 0),
    };
  };

  /* card anchor points (pills sit above the card, so offset the top) */
  const anchors = (n: StepNode) => {
    const { cx, top } = place(n);
    return {
      top: { x: cx, y: top + (n.kind ? PILL_OFFSET : 0) },
      bottom: { x: cx, y: top + (heights[n.id] ?? 90) },
    };
  };

  const bezier = (edge: { from: string; to: string }) => {
    const from = anchors(NODES.find((n) => n.id === edge.from)!).bottom;
    const to = anchors(NODES.find((n) => n.id === edge.to)!).top;
    const k = Math.min(Math.max(Math.abs(to.y - from.y) * 0.55, 24), 84);
    return `M ${from.x} ${from.y} C ${from.x} ${from.y + k}, ${to.x} ${to.y - k}, ${to.x} ${to.y}`;
  };

  /* ── dragging ── */
  const onPointerDown = (node: StepNode) => (event: React.PointerEvent<HTMLDivElement>) => {
    if ((event.target as Element).closest("[data-ui]")) return;
    const off = offsets[node.id];
    drag.current = {
      id: node.id,
      startX: event.clientX,
      startY: event.clientY,
      baseDx: off?.dx ?? 0,
      baseDy: off?.dy ?? 0,
      moved: false,
    };
    (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
  };

  const onPointerMove = (node: StepNode) => (event: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d || d.id !== node.id) return;
    const dx = d.baseDx + event.clientX - d.startX;
    const dy = d.baseDy + event.clientY - d.startY;
    if (!d.moved && Math.hypot(dx - d.baseDx, dy - d.baseDy) < 3) return;
    d.moved = true;

    /* keep the card inside the canvas */
    const { w } = place(node);
    const h = heights[node.id] ?? 90;
    const baseCx = node.x * cw;
    const baseTop = rowY[rows.indexOf(node.row)];
    const cx = Math.min(Math.max(baseCx + dx, w / 2 + 8), cw - w / 2 - 8);
    const top = Math.min(Math.max(baseTop + dy, 8), canvasH - h - 8);
    const nextOffset = { dx: cx - baseCx, dy: top - baseTop };
    setOffsets((current) => ({ ...current, [node.id]: nextOffset }));
    onNodeMove?.(node.id, nextOffset);
  };

  const onPointerUp = (node: StepNode) => () => {
    const d = drag.current;
    if (d?.id === node.id) {
      /* a real drag shouldn't also toggle selection */
      if (d.moved) setTimeout(() => (drag.current = null), 0);
      else drag.current = null;
    }
  };

  const wasDragged = () => drag.current?.moved === true;

  const nudgeNode = (node: StepNode, event: React.KeyboardEvent<HTMLElement>) => {
    if (event.target !== event.currentTarget) return;
    const delta = event.shiftKey ? 24 : 12;
    const movement = {
      ArrowLeft: { x: -delta, y: 0 },
      ArrowRight: { x: delta, y: 0 },
      ArrowUp: { x: 0, y: -delta },
      ArrowDown: { x: 0, y: delta },
    }[event.key];
    if (!movement) return;
    event.preventDefault();
    event.stopPropagation();
    const { w } = place(node);
    const h = heights[node.id] ?? 90;
    const baseCx = node.x * cw;
    const baseTop = rowY[rows.indexOf(node.row)];
    const current = offsets[node.id] ?? { dx: 0, dy: 0 };
    const cx = Math.min(Math.max(baseCx + current.dx + movement.x, w / 2 + 8), cw - w / 2 - 8);
    const top = Math.min(Math.max(baseTop + current.dy + movement.y, 8), canvasH - h - 8);
    const nextOffset = { dx: cx - baseCx, dy: top - baseTop };
    setOffsets((all) => ({ ...all, [node.id]: nextOffset }));
    onNodeMove?.(node.id, nextOffset);
  };

  const isLit = (edge: { from: string; to: string }) =>
    selected === edge.from || selected === edge.to;

  return (
    <div
      ref={canvasRef}
      className={`relative w-full select-none overflow-hidden ${shape.container} bg-[var(--page)] shadow-[var(--shadow-hairline)]`}
      style={{
        height: canvasH,
        backgroundImage: "radial-gradient(var(--line-strong) 1px, transparent 1.25px)",
        backgroundSize: "22px 22px",
        backgroundPosition: "center",
      }}
    >
      {/* connectors */}
      <svg width={cw} height={canvasH} className="pointer-events-none absolute inset-0">
        {EDGES.map((edge) => (
          <path
            key={`${edge.from}-${edge.to}`}
            d={bezier(edge)}
            fill="none"
            stroke={isLit(edge) ? "var(--bui-focus)" : "var(--line-strong)"}
            strokeWidth="1.25"
            className="transition-[stroke] duration-160"
          />
        ))}
      </svg>

      {/* nodes */}
      {NODES.map((node) => {
        const { w, cx, top } = place(node);
        const active = selected === node.id;
        return (
          <div
            key={node.id}
            ref={(el) => {
              if (el) nodeRefs.current.set(node.id, el);
              else nodeRefs.current.delete(node.id);
            }}
            onPointerDown={onPointerDown(node)}
            onPointerMove={onPointerMove(node)}
            onPointerUp={onPointerUp(node)}
            onKeyDown={(event) => nudgeNode(node, event)}
            tabIndex={node.condition ? 0 : undefined}
            role={node.condition ? "group" : undefined}
            aria-label={
              node.condition
                ? "If or else workflow step. Use arrow keys to move the step."
                : undefined
            }
            className="absolute flex -translate-x-1/2 touch-none flex-col items-start gap-1.5"
            style={{ left: cx, top, width: w, zIndex: drag.current?.id === node.id ? 2 : 1 }}
          >
            {node.kind && (
              <span
                className={`inline-flex h-6 items-center ${shape.item} px-2 text-[11px] font-medium`}
                style={{
                  background: mix(node.kind.hue, 14, "var(--page)"),
                  color: mix(node.kind.hue, 80, "var(--ink)"),
                }}
              >
                {node.kind.label}
              </span>
            )}
            {node.condition ? (
              <div
                className={`w-full ${shape.container} bg-[var(--surface)] shadow-[var(--shadow-card)] transition-shadow duration-80 hover:shadow-[var(--shadow-raised)]`}
              >
                <ConditionBody onChange={onConditionChange} />
              </div>
            ) : (
              <button
                type="button"
                onClick={() => {
                  if (wasDragged()) return;
                  setSelected(active ? null : node.id);
                }}
                onKeyDown={(event) => nudgeNode(node, event)}
                aria-pressed={active}
                aria-label={`${node.title}. Use arrow keys to move this workflow step.`}
                className={`w-full cursor-pointer ${shape.container} bg-[var(--surface)] text-left outline-none
                  transition-shadow duration-80
                  ${
                    active
                      ? "shadow-[var(--shadow-raised)] ring-1 ring-[#6B97FF]"
                      : "shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-raised)]"
                  }`}
